package com.example.payment.architecturetest;

import static com.tngtech.archunit.library.Architectures.layeredArchitecture;

import com.tngtech.archunit.core.domain.JavaClasses;
import com.tngtech.archunit.core.importer.ClassFileImporter;
import com.tngtech.archunit.core.importer.ImportOption;
import org.junit.jupiter.api.Test;

/**
 * Guards the module boundaries of the payment-authorization build: domain code must stay
 * free of application/infrastructure concerns, application code must stay free of
 * infrastructure/framework details, and only infrastructure is allowed to depend on
 * technical details (HTTP client, filesystem, Jackson, Spring, ...).
 *
 * This check inspects compiled bytecode across every module, so it is intentionally kept
 * out of the fast, save-triggered unit test suite (see payment-architecture-test/pom.xml)
 * and run explicitly, e.g. in CI, via `mvn verify -Parchitecture-test`.
 */
class LayeredArchitectureTest {

    @Test
    void domain_application_and_infrastructure_stay_in_their_own_layer() {
        JavaClasses classes = new ClassFileImporter()
                .withImportOption(ImportOption.Predefined.DO_NOT_INCLUDE_TESTS)
                .importPackages("com.example.payment");

        layeredArchitecture()
                .consideringAllDependencies()
                .layer("Domain").definedBy("com.example.payment.domain..")
                .layer("Application").definedBy("com.example.payment.application..")
                .layer("Infrastructure").definedBy("com.example.payment.infrastructure..")
                .layer("App").definedBy("com.example.payment.app..")

                .whereLayer("Domain").mayOnlyBeAccessedByLayers("Application", "Infrastructure", "App")
                .whereLayer("Application").mayOnlyBeAccessedByLayers("Infrastructure", "App")
                .whereLayer("Infrastructure").mayOnlyBeAccessedByLayers("App")
                .whereLayer("App").mayNotBeAccessedByAnyLayer()

                .check(classes);
    }
}

